 return (r?`<p><strong>Rapporto:</strong> ${esc(labels[r.employment_relationship]||r.employment_relationship)} · Contratto: ${esc(labels[r.contract_type]||r.contract_type)} · Impegno: ${esc(labels[r.workload]||r.workload)}</p>${r.contradictory?'<p>Modalità discordanti: chiarire il contratto prima del contatto.</p>':''}`:'')+(n?`<p><strong>Identità:</strong> ${esc(n.selected_name)}<br>Ragione sociale: ${esc(n.legal_name||'Da verificare')}<br>Valore originale conservato: ${esc(n.original_name)}<br>Titolo della pagina: ${esc(n.page_title)}</p>`:'')+(d?`<p><strong>Risoluzione:</strong> ${esc(d.declared_actor)} · dominio ufficiale ${d.official_domain_verified?'verificato':'da verificare'}; ruolo ${d.role_verified?'riscontrato':'da verificare'}. ${link(d.publisher_source,'Fonte iniziale')}</p>`:'');
