function renderRecommendedJobs(){
 $('#main').innerHTML=`<div id="commercial-root">${commercialCampaign()}<div class="sectionhead"><div><h2>Annunci consigliati</h2><p>Compatibili con il tuo profilo, da verificare personalmente. Non sono commesse commerciali confermate.</p></div></div><nav class="actions" aria-label="Tipo di risultati"><button data-commercial-view="recommended" aria-pressed="true">Annunci consigliati</button><button data-commercial-view="opportunities" aria-pressed="false">Valutazioni commerciali</button><button data-commercial-view="discovery" aria-pressed="false">Indizi e filtri discovery</button></nav><nav class="actions job-categories" aria-label="Attualità annunci">${[["recent","Recenti"],["verify","Da verificare"],["archived","Archiviati"]].map(([k,v])=>`<button data-job-category="${k}" aria-pressed="${commercialJobCategory===k}">${v}</button>`).join('')}</nav><div class="panel job-filters"><label>Rapporto<select data-job-filter="employment">${[["freelance","Collaborazioni e rapporti da chiarire"],["employment","Solo dipendenti"],["all","Tutti i rapporti"]].map(([k,v])=>`<option value="${k}" ${commercialJobEmployment===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Finestra pubblicazione · giorni<input type="number" min="1" max="90" data-job-filter="max_job_age_days" value="${commercialJobAge}"></label><label>Valutazione personale<select data-job-filter="review">${[['','Tutti'],['high','Alta compatibilità'],['to_review','Da verificare'],['interesting','Interessanti'],['reviewed','Già valutati'],['not_interesting','Non interessanti']].map(([k,v])=>`<option value="${k}" ${commercialJobReview===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Motore<select data-job-filter="engine"><option value="">Tutti i motori di annunci</option>${Object.entries(S.commercial_engines).filter(([k])=>k!=='WEBSITE_REBUILD').map(([k,v])=>`<option value="${k}" ${commercialJobEngine===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>Campagna<select data-job-filter="scope"><option value="current" ${commercialJobScope==='current'?'selected':''}>Campagna attuale</option><option value="all" ${commercialJobScope==='all'?'selected':''}>Tutto lo storico</option></select></label><label>Titolo o azienda<input type="search" data-job-filter="search" value="${esc(commercialJobSearch)}" placeholder="Cerca negli annunci"></label></div><div id="commercial-results" aria-live="polite">Caricamento…</div></div>`;
 loadRecommendedJobs();
}
function recommendedJobCard(r){
 const confidence={HIGH:'Alta',MEDIUM:'Media',LOW:'Bassa'}[r.evidence_confidence]||'Sconosciuta';
 return `<article class="panel recommended-job" data-job-id="${Number(r.id)}"><div class="commercial-card-heading"><div><div class="tags"><span class="tag">Annuncio da verificare</span><span class="tag">${esc(jobReviewLabels[r.review_status])}</span></div><h3>${esc(r.title)}</h3><p><strong>${esc(r.company.value||'Azienda non identificata')}</strong> · ${esc(r.location.value||'Località non verificata')}</p><p class="small muted">Fonte: ${esc(r.source)} · ${r.activity?.published_at?dt(r.activity.published_at):'Data non verificata'}</p></div><div class="job-score"><strong>${Number(r.compatibility_score)}<small>/100</small></strong><span>Compatibilità</span></div></div>${jobActivityCard(r)}<p><strong>Affidabilità delle informazioni: ${confidence}</strong><br><span class="small">${r.original_read?'Richiesta letta nella fonte; apertura e contratto richiedono comunque verifica.':'Contenuto non completamente verificato. Apri l’annuncio per controllare i dettagli.'}</span></p><div class="tags">${r.skills.map(s=>`<span class="tag">${esc(s)}</span>`).join('')}</div><p><strong>Tipo di collaborazione:</strong> ${esc(r.relationship.label)}${r.relationship.type!=='UNKNOWN'&&!r.relationship.verified_on_original?' · indicazione nei metadati, non confermata sulla pagina':''}</p><ul>${r.score_detail.filter(d=>d.points!==0).map(d=>`<li>${esc(d.reason)} (${d.points>0?'+':''}${Number(d.points)})</li>`).join('')}</ul><details><summary>Prove, punteggio e informazioni mancanti</summary><p class="small">Compatibilità non significa probabilità di assunzione. Stato commerciale conservato: ${esc(commercialLabels[r.official_state]||r.official_state)}.</p><ul>${r.missing.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>${r.provenance.map(p=>`<p><strong>${esc(jobProvenanceLabels[p.provenance]||p.provenance)}</strong></p><blockquote>${esc(p.value)}</blockquote>`).join('')}<p class="small">Azienda: ${esc(jobProvenanceLabels[r.company.provenance])}. Località: ${esc(jobProvenanceLabels[r.location.provenance])}.</p>${r.score_detail.map(d=>`<p class="small">${Number(d.points)} · ${esc(d.reason)}</p>`).join('')}</details>${jobObservationForm(r)}<div class="actions job-actions"><a class="button primary" href="${esc(r.original_url)}" target="_blank" rel="noopener noreferrer">Apri annuncio</a>${Object.entries(jobReviewLabels).map(([k,v])=>`<button data-job-review="${k}" data-id="${Number(r.id)}" data-revision="${Number(r.revision_id)}" aria-pressed="${r.review_status===k}" ${r.review_status===k?'disabled':''}>${v}</button>`).join('')}</div><p class="small muted">Apertura manuale della fonte. Nessuna candidatura automatica.</p></article>`;
}
async function loadRecommendedJobs(){
 const seq=++commercialSequence,params=new URLSearchParams({offset:commercialOffset,limit:20,employment:commercialJobEmployment,review:commercialJobReview,engine:commercialJobEngine,search:commercialJobSearch,category:commercialJobCategory,max_job_age_days:commercialJobAge});
 if(commercialJobScope==='current'&&S.campaign)params.set('campaign',S.campaign.id);
 try{const data=await api('/commercial/recommendations?'+params);if(seq!==commercialSequence||!commercialRecommended||!$('#commercial-results'))return;
 $('#commercial-results').innerHTML=`<p class="small muted">${Number(data.total)} annunci in questa vista · Recenti ${Number(data.category_counts?.recent||0)} · Da verificare ${Number(data.category_counts?.verify||0)} · Archiviati ${Number(data.category_counts?.archived||0)} · Duplicati raggruppati. “Tutti” nasconde quelli segnati non interessanti.</p>${data.items.map(recommendedJobCard).join('')||'<div class="empty"><h3>Nessun annuncio con questi filtri</h3><p>Nessun annuncio soddisfa questi filtri. Controlla anche Da verificare e Archiviati: una data sconosciuta non dimostra che l’annuncio sia recente.</p></div>'}${data.total>data.limit?`<div class="actions"><button data-commercial-page="previous" ${!data.offset?'disabled':''}>Precedenti</button><button data-commercial-page="next" ${data.offset+data.limit>=data.total?'disabled':''}>Successive</button></div>`:''}`;
 }catch(error){if(seq===commercialSequence&&$('#commercial-results'))$('#commercial-results').innerHTML=`<p role="alert">${esc(error.message)}</p><button data-commercial-retry>Riprova</button>`}
}
document.addEventListener('input',e=>{const key=e.target.dataset.jobFilter;if(!key)return;const v=e.target.value;if(key==='employment')commercialJobEmployment=v;if(key==='review')commercialJobReview=v;if(key==='engine')commercialJobEngine=v;if(key==='scope')commercialJobScope=v;if(key==='search')commercialJobSearch=v;if(key==='max_job_age_days'){const n=Number(v);if(!Number.isInteger(n)||n<1||n>90)return;commercialJobAge=n;}commercialOffset=0;commercialSequence++;clearTimeout(commercialTimer);commercialTimer=setTimeout(loadRecommendedJobs,key==='search'?250:0)});

function commercialAuditCoverage(c){return `<details class="audit-coverage"><summary>Verifiche browser: ${c.completed?'completate':'parziali o non eseguite'}</summary>${c.viewports.map(p=>`<p><strong>${Number(p.viewport)} px</strong> · ${esc(p.observed.join(' · ')||'Nessuna osservazione salvata')}<br>${esc(p.missing.join(' · '))}</p>`).join('')||'<p>Nessun viewport verificato.</p>'}<p>${esc(c.failure_codes.join(' · '))}</p><p class="small">${esc(c.missing.join(' · '))}</p></details>`}

// Phase 4.5: freshness is admission, not a technical-score bonus.
function jobActivityCard(r){const a=r.activity;if(!a)return '';return `<section class="job-activity" aria-label="Attualità e candidabilità"><div class="tags"><span class="tag">${esc({recent:'Annuncio recente',verify:'Da verificare',archived:'Archiviato'}[a.category]||'Collaborazione continuativa')}</span><span class="tag">${esc({OPEN_CONFIRMED:'Apertura osservata · non garantisce accettazione',CLOSED_CONFIRMED:'Candidature chiuse',OPEN_UNKNOWN:'Apertura da verificare'}[a.application_status])}</span></div><p><strong>Pubblicazione:</strong> ${a.published_at?esc(dt(a.published_at))+' · '+Number(a.age_days)+' giorni':a.publication_interval?'Data relativa documentata (intervallo)':'Data non verificata'}</p><p><strong>Lavoro dall’Italia:</strong> ${esc({GEO_COMPATIBLE:'Compatibile secondo le indicazioni disponibili',GEO_INCOMPATIBLE:'Non compatibile con lavoro dall’Italia',GEO_UNKNOWN:'Da verificare'}[a.geographic_eligibility])}</p>${a.reasons.map(v=>`<p class="small">${esc(v)}</p>`).join('')}${a.conflicts.length?'<p role="status"><strong>Fonti discordanti: verifica necessaria.</strong> Le osservazioni precedenti sono conservate.</p>':''}<details><summary>Prove di data, apertura e geografia</summary>${a.evidence.map(e=>`<p class="small"><strong>${esc(e.provenance==='MANUAL_OBSERVATIONS'?'Verifica manuale':jobProvenanceLabels[e.provenance]||e.provenance)}</strong> · ${esc(e.kind)} · ${e.observed_at?esc(dt(e.observed_at)):'Osservazione non datata'}<br>${esc(e.quote||e.value||'Dato non disponibile')} ${e.url?link(e.url,'Fonte'):''}</p>`).join('')||'<p>Nessuna prova sufficiente salvata.</p>'}</details></section>`}
function jobObservationForm(r){return `<details class="job-observation"><summary>Registra una verifica manuale</summary><div class="job-observation-fields" data-observation-id="${Number(r.id)}" data-revision="${Number(r.revision_id)}"><p class="small">Compila dopo aver aperto l’annuncio. Il pulsante Apply da solo non conferma l’apertura. Non modifica la qualifica commerciale.</p><label>Ho osservato<select data-observation="kind"><option value="closed">Candidature chiuse</option><option value="open">Candidature ancora aperte</option><option value="too_old">Annuncio oltre la finestra di ${commercialJobAge} giorni</option><option value="geo_incompatible">Non compatibile con lavoro dall’Italia</option><option value="publication_date">Data di pubblicazione esatta</option></select></label><label>Data e ora della verifica · ora locale<input type="datetime-local" data-observation="observed_at" required></label><label>Pubblicazione · solo se nota esattamente<input type="date" data-observation="published_at"></label><label>Nota / testo osservato<textarea data-observation="note" maxlength="2000" placeholder="Non convertire «circa un anno fa» in una data inventata."></textarea></label><button data-job-observation-save>Salva osservazione</button></div></details>`}
document.addEventListener('click',async e=>{
 const category=e.target.closest('[data-job-category]');if(category){commercialJobCategory=category.dataset.jobCategory;commercialOffset=0;renderRecommendedJobs();return}
 const button=e.target.closest('[data-job-observation-save]');if(!button)return;
 const fields=button.closest('[data-observation-id]'),value=k=>fields.querySelector(`[data-observation="${k}"]`).value;
 if(!value('observed_at')){toast('Indica quando hai verificato l’annuncio.');return}
 button.disabled=true;
 try{await api('/commercial/opportunities/'+fields.dataset.observationId+'/job-observation',{revision_id:Number(fields.dataset.revision),kind:value('kind'),observed_at:new Date(value('observed_at')).toISOString(),published_at:value('published_at'),note:value('note'),max_job_age_days:commercialJobAge});await loadRecommendedJobs();toast('Osservazione manuale salvata. Storico commerciale invariato.')}
 catch(error){toast(error.message)}finally{button.disabled=false}
});

// 5.0: read-only forecast. A forecast never invokes a provider or creates a job.
function renderSearchPlan(p){
 const b=p.maximums;
 const language=v=>({it:'Italiano',en:'Inglese'}[v]||v), geography=v=>({TIER_1:'Italia',TIER_2:'Remoto Italia ed Europa',TIER_3:'Remoto internazionale'}[v]||v);
 const source=v=>({official_company:'Siti aziendali',official_careers:'Pagine lavoro ufficiali',agency_partnership:'Collaborazioni con agenzie',project_marketplace:'Richieste di progetto',social_post:'Post pubblici',job_board:'Annunci professionali'}[v]||v);
 return `<p><strong>${esc(p.mode.toUpperCase())}: ${p.planned_queries} query iniziali / ${p.available_queries} disponibili</strong> · ${p.selected_strategies.length} strategie previste.</p><p>Lingue: ${p.languages.map(v=>esc(language(v))).join(', ')} · ${p.geography_tiers.map(v=>esc(geography(v))).join(', ')}.</p><p>Massimi: <strong>${b.max_serper_credits} crediti Serper stimati</strong>, ${b.max_http_reads} letture HTTP, ${b.max_browser_runs} audit; AI ${b.ai_max_calls} chiamate / ${b.ai_max_estimated_usd} USD. Saldo e costo monetario Serper sconosciuti.</p><p>${Math.round(b.max_runtime_seconds/60)} minuti di lavoro contabilizzato complessivo. ${esc(p.duration_note)}</p><p class="small">${esc(p.coverage_note)}</p><details><summary>Query e priorità previste (${p.queries.length})</summary><ol class="search-plan-queries">${p.queries.map(q=>`<li><strong>${esc(q.intent)}</strong> · ${esc(language(q.language))} · ${esc(q.region)} · priorità ${q.priority}<p>${esc(q.query)} -filetype:pdf</p><span class="small">${esc(source(q.source_preference))} · ${q.allocation.policy==='exploration_turn'?'Esplorazione di una strategia':'Priorità basata sui risultati osservati'}</span></li>`).join('')}</ol></details><details><summary>Query non selezionate (${p.excluded_queries.length})</summary><ul>${p.excluded_queries.map(q=>`<li>${esc(q.query)} · ${esc(q.reason==='already_explored_within_6h'?'Già esplorata nelle ultime 6 ore':'Limite di query del motore')}</li>`).join('')}</ul></details>${p.authorization_required?'<label class="commercial-checkbox"><input type="checkbox" id="commercial-deep-authorization" '+(commercialDeepAuthorized?'checked':'')+'> Autorizzo questi massimi per la prossima ricerca Deep. La ricerca partirà solo con Avvia.</label>':''}`;
}
document.addEventListener('click',async e=>{
 const button=e.target.closest('[data-search-plan]');if(!button)return;
 button.disabled=true;commercialDeepAuthorized=false;
 try{commercialSearchPlan=await api('/commercial/search-plan',{filters:{commercial_engines:Object.keys(S.commercial_engines),regions:commercialRegions||S.campaign?.filters?.regions||S.commercial_regions,mode:commercialMode,max_job_age_days:commercialNewJobAge}});const target=$('#search-plan-result');if(target)target.innerHTML=renderSearchPlan(commercialSearchPlan)}catch(error){toast(error.message)}finally{button.disabled=false}
});
document.addEventListener('change',e=>{
 if(e.target.id==='commercial-deep-authorization')commercialDeepAuthorized=e.target.checked;
 if(e.target.id==='commercial-mode'||e.target.id==='commercial-job-age'||e.target.dataset.commercialRegion){commercialSearchPlan=null;commercialDeepAuthorized=false;const target=$('#search-plan-result');if(target)target.innerHTML='<p>Piano da aggiornare: premi Anteprima ricerca.</p>'}
});

function commercialDemandDetails(b){
 const d=b.demand_assessment;if(!d)return '';
 const types={BUYER_DEMAND:'Richiesta del cliente',SUPPLIER_OFFER:'Offerta di servizi',COMPLETED_PROJECT:'Progetto già concluso',JOB_AGGREGATION:'Elenco di annunci',INDIVIDUAL_JOB:'Annuncio individuale',EDITORIAL_CONTENT:'Contenuto informativo',DIRECTORY:'Elenco di fornitori',STANDING_COLLABORATION:'Disponibilità a collaborazioni',UNKNOWN:'Tipo di pagina da verificare'};
 const geo={GEO_COMPATIBLE_CONFIRMED:'Compatibilità con l’Italia documentata',GEO_INCOMPATIBLE_CONFIRMED:'Vincoli geografici incompatibili',GEO_UNKNOWN:'Lavoro dall’Italia da verificare'};
 return `<div class="panel"><strong>Verifica della domanda</strong><p>${esc(types[d.page_type]||d.page_type)}</p><p>Editore: ${esc(d.actors?.publisher||'Sconosciuto')}<br>Committente: ${esc(d.actors?.buyer||'Non identificato')}<br>${esc(geo[d.geography?.status]||'Geografia sconosciuta')}</p><p>Fonte originale: ${d.original_available?'disponibile':'non verificata'} · Qualità delle prove: ${esc(d.evidence_level)} / 4</p>${d.evidence?.request_quote?'<blockquote>'+esc(d.evidence.request_quote)+'</blockquote>':''}</div>`;
}

function commercialCandidateStages(c){
 const x=c?.candidate_stages;if(!x||x.policy!=='deep_review_quota')return '';
 return `<p class="small muted">Ricevuti: ${esc(x.RAW_RESULTS)} · Prefiltrati: ${esc(x.SCREENED_RESULTS)} · In coda o già elaborati: ${esc(x.ADMITTED_CANDIDATES)} · Approfondimenti avviati: ${esc(x.DEEP_REVIEW_CANDIDATES)}. Solo gli approfondimenti consumano la quota candidati.</p>`;
}
